INK='#14213D'; MUTED='#52627A'; LINE='#334155'; PURPLE='#6D28D9'
def txt(x,y,s,size=24,fill=INK,anchor='mm',bold=False): d.text((x,y),s,font=F(size,bold),fill=fill,anchor=anchor)
def box(x,y,w,h,title,lines,fill,foot=None,outline=LINE):
 d.rounded_rectangle((x,y,x+w,y+h),radius=24,fill=fill,outline=outline,width=4); txt(x+w/2,y+36,title,28,bold=True); yy=y+84
