def arrow(x1,y1,x2,y2,color=LINE,width=6):
 d.line((x1,y1,x2,y2),fill=color,width=width); a=math.atan2(y2-y1,x2-x1); L=24; d.polygon([(x2,y2),(x2-L*math.cos(a-.45),y2-L*math.sin(a-.45)),(x2-L*math.cos(a+.45),y2-L*math.sin(a+.45))],fill=color)
def curve(points,color=LINE,width=6): d.line(points,fill=color,width=width,joint='curve'); arrow(*points[-2],*points[-1],color=color,width=width)
